advancedCss:
/* Aurora Bench — the advancedCss showcase at FULL throttle (R6-3, reworked R8):
   every trick rides the STABLE selector vocabulary only (theme-compat).
   Best-effort by contract: a future UI refactor may need touch-ups.
   R8 pass: glass list card, aureole on hover, breathe-with-texture active,
   full tab-glyph re-skin, connector current, deeper Chrome arcs, the
   point-symmetric console frame, and the second global glow surge. */

/* 0. The cursor — a glowing aqua orb (data-URL SVG; img-src data: lane).
      Interactive surfaces keep the pointer fallback. */
body { cursor: url(data:image/svg+xml;base64,) 11 11, auto; }
a, button, .row-tag-chip, .row-tag-dot, .tag-more, .view-tab,
.vbm-toolbar button, menu.menu-item, select, input[type=checkbox] {
    cursor: url(data:image/svg+xml;base64,) 11 11, pointer;
}

/* 1. The aurora header film — a slow polar drift over the search bar;
      reduced-motion clamps all animation globally (nothing depends on it). */
@keyframes aurora-drift {
    0% { background-position: 0% 0%; }
    100% { background-position: 200% 100%; }
}
#search {
    background-image: linear-gradient(100deg,
        color-mix(in srgb, #b14aed 14%, transparent),
        transparent 42%,
        color-mix(in srgb, #7ee8fa 14%, transparent) 58%,
        transparent);
    background-size: 220% 100%;
    animation: aurora-drift 26s linear infinite;
}

/* 2. Glass floats — translucent + the theme's overlay-blur token does the
      frosting; the token elev gains an alpha wash so there is something to
      blur. */
.vbm-dropdown-list,
menu[type=context],
.dialog {
    background-color: color-mix(in srgb, #1a2038 74%, transparent);
}

/* 2b. R8-2: the view card is GLASS — the aurora sky (body::before canvas
      layer) shows through the list area instead of stopping at its border.
      A 55% bg wash + the backdrop frost keep every row on a dark base, so
      #e8ecf8 text never loses its contrast. */
#views {
    background-color: color-mix(in srgb, var(--vbm-bg) 46%, transparent);
    backdrop-filter: blur(7px) saturate(1.25);
}

/* 3. 流光溢彩 — R8-3: the spinning conic aureole rides HOVER rows now (it
      was always a hover-language halo; the active row has its own voice). */
@property --aureole { syntax: '<angle>'; inherits: false; initial-value: 0deg; }
@keyframes aureole-spin { to { --aureole: 360deg; } }
#tree ul li a:hover,
#results ul li a:hover,
#recent-list ul li a:hover,
#dupes-list ul li a:hover,
#tabgroups-list ul li a:hover,
#staging-list ul li a:hover,
#dead-list ul li a:hover,
#stats-list ul li a:hover {
    position: relative;
}
#tree ul li a:hover::after,
#results ul li a:hover::after,
#recent-list ul li a:hover::after,
#dupes-list ul li a:hover::after,
#tabgroups-list ul li a:hover::after,
#staging-list ul li a:hover::after,
#dead-list ul li a:hover::after,
#stats-list ul li a:hover::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: 6px;
    padding: 1.5px;
    background: conic-gradient(from var(--aureole),
        #7ee8fa, #b14aed, #ff7ad9, #ffc857, #7ee8fa);
    -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
    -webkit-mask-composite: xor;
            mask-composite: exclude;
    animation: aureole-spin 3.2s linear infinite;
    pointer-events: none;
}

/* 3b. R8-3: the ACTIVE row breathes AND keeps its material — the speckle
      tile rides OVER the active gradient permanently, so even at the
      breathe minimum (brightness 1.0) the row reads as textured matter,
      never a bare outline. */
#tree ul li a
#results ul li a
#staging-list ul li a
#dead-list ul li a
#stats-list ul li a.active {
    background-image: url(data:image/svg+xml;base64,), var(--vbm-row-active-bg);
}

/* 4. Material hover — rows pick up the same fine speckle texture (SVG
      turbulence tile) under the standard hover wash, now paired with the
      aureole ring. */
#tree ul li a:hover,
#results ul li a:hover,
#recent-list ul li a:hover,
#dupes-list ul li a:hover,
#tabgroups-list ul li a:hover,
#staging-list ul li a:hover,
#dead-list ul li a:hover,
#stats-list ul li a:hover {
    background-image: url(data:image/svg+xml;base64,);
}

/* 5. Chrome-弧线 tabs (horizontal strips: popup / side panel) — the classic
      trapezoid with outward-curved bottom corners, painted by inverse
      radial gradients on the Selected tab. R8-6: the dome and both corner
      fans deepen 9px → 13px, the arc finally reads as an arc. The rail
      (standalone) keeps its own slanted cut below. */
body:not(.standalone-mode) #view-tabs {
    gap: 2px;
    /* R12.1: the strip is FULLY transparent — the wash rectangle read as a
       second card fighting the active tab's own rounded box. What remains:
       icons, badges, and the active tab's arc rendering. */
    background: transparent;
    backdrop-filter: none;
    border: 0;
    border-radius: 0;
}
body:not(.standalone-mode) .view-tab {
    position: relative;
    border-radius: 13px 13px 0 0;
    border: 1px solid transparent;
    border-bottom: none;
    margin-bottom: -1px;
}
body:not(.standalone-mode) .view-tab[aria-selected="true"] {
    /* R13: the active tab is FROSTED GLASS — the same recipe as the list
       card, so tab + card read as one continuous pane */
    background: color-mix(in srgb, var(--vbm-bg) 46%, transparent);
    backdrop-filter: blur(7px) saturate(1.25);
    border-color: var(--vbm-border);
}
body:not(.standalone-mode) .view-tab[aria-selected="true"]::before,
body:not(.standalone-mode) .view-tab[aria-selected="true"]::after {
    content: '';
    position: absolute;
    bottom: -1px;
    width: 13px;
    height: 13px;
    pointer-events: none;
}
body:not(.standalone-mode) .view-tab[aria-selected="true"]::before {
    left: -13px;
    background: radial-gradient(circle at 0 0, transparent 12.5px,
        color-mix(in srgb, var(--vbm-bg) 46%, transparent) 13px);
    clip-path: inset(50% 0 0 0);
}
body:not(.standalone-mode) .view-tab[aria-selected="true"]::after {
    right: -13px;
    background: radial-gradient(circle at 100% 0, transparent 12.5px,
        color-mix(in srgb, var(--vbm-bg) 46%, transparent) 13px);
    clip-path: inset(50% 0 0 0);
}
body:not(.standalone-mode) .view-tab[aria-selected="true"] .tab-icon {
    filter: drop-shadow(0 0 9px color-mix(in srgb, #7ee8fa 75%, transparent));
}

/* 6. R8-4: the tab glyphs swap to the aurora ink — the FULL set now, all
      nine view tabs (the native strokes hide; title/aria carry meaning). */
#view-tab-tree .tab-icon svg,
#view-tab-search .tab-icon svg,
#view-tab-tabgroups .tab-icon svg,
#view-tab-recent .tab-icon svg,
#view-tab-stats .tab-icon svg,
#view-tab-dead .tab-icon svg,
#view-tab-dupes .tab-icon svg,
#view-tab-recentcenter .tab-icon svg,
#view-tab-home .tab-icon svg { display: none; }
#view-tab-tree .tab-icon,
#view-tab-search .tab-icon,
#view-tab-tabgroups .tab-icon,
#view-tab-recent .tab-icon,
#view-tab-stats .tab-icon,
#view-tab-dead .tab-icon,
#view-tab-dupes .tab-icon,
#view-tab-recentcenter .tab-icon,
#view-tab-home .tab-icon {
    width: 16px;
    height: 16px;
    background: center / contain no-repeat;
}
#view-tab-tree .tab-icon { background-image: url(data:image/svg+xml;base64,); }
#view-tab-search .tab-icon { background-image: url(data:image/svg+xml;base64,); }
#view-tab-tabgroups .tab-icon { background-image: url(data:image/svg+xml;base64,); }
#view-tab-recent .tab-icon { background-image: url(data:image/svg+xml;base64,); }
#view-tab-stats .tab-icon { background-image: url(data:image/svg+xml;base64,); }
#view-tab-dead .tab-icon { background-image: url(data:image/svg+xml;base64,); }
#view-tab-dupes .tab-icon { background-image: url(data:image/svg+xml;base64,); }
#view-tab-recentcenter .tab-icon { background-image: url(data:image/svg+xml;base64,); }
#view-tab-home .tab-icon { background-image: url(data:image/svg+xml;base64,); }

/* 7. R8-7: the console frame — the list card's WHOLE outline is shaped
      now. Point-symmetric cuts (TR/BL 22px, TL/BR 10px) read as a drafted
      chamfer language, not a glitch; each big cut carries an accent seam
      riding the diagonal. The card is glass (2b), so the sky glows through
      the frame. */
#views {
    /* R13: the top corners are SHAPED too — half-depth 11px cuts, glowing
       seam accents riding background layers; and keyed off the strip's
       data-edge markers, the corner under the ACTIVE tab stays square so
       the tab's vertical box and the card read as one piece (popup only —
       the standalone rail welds sideways, the constant cuts stand) */
    clip-path: polygon(
        0 11px, 11px 0,
        calc(100% - 11px) 0, 100% 11px,
        100% calc(100% - 22px), calc(100% - 22px) 100%,
        22px 100%, 0 calc(100% - 22px));
    background-image:
        linear-gradient(45deg, transparent 30%,
            color-mix(in srgb, #7ee8fa 80%, transparent) 50%,
            color-mix(in srgb, #b14aed 70%, transparent) 60%, transparent 74%),
        linear-gradient(135deg, transparent 30%,
            color-mix(in srgb, #7ee8fa 80%, transparent) 50%,
            color-mix(in srgb, #b14aed 70%, transparent) 60%, transparent 74%);
    /* the 11×11 box pins the gradient diagonal EXACTLY on the cut edge
       ((W-11,0)→(W,11) for TR; mirrored for TL) — the outer half of the
       band clips away, the inner half hugs the edge. R13.1: the earlier
       19px box offset the diagonal ~7px off the edge. */
    background-size: 11px 11px, 11px 11px;
    /* border-box origin: pin the box to the TRUE corner (padding-box origin
       was inset by the border, sliding the seam ~1px+ inward) */
    background-origin: border-box;
    background-position: right 0 top 0, left 0 top 0;
    background-repeat: no-repeat, no-repeat;
}
body:not(.standalone-mode) #view-tabs[data-edge-start] + #views {
    /* active tab first: the top-left weld is square — TL seam retires */
    clip-path: polygon(
        0 0, calc(100% - 11px) 0, 100% 11px,
        100% calc(100% - 22px), calc(100% - 22px) 100%,
        22px 100%, 0 calc(100% - 22px));
    background-position: right 0 top 0, -19px -19px;
}
body:not(.standalone-mode) #view-tabs[data-edge-end] + #views {
    /* active tab last: top-right weld square — TR seam retires */
    clip-path: polygon(
        0 11px, 11px 0, 100% 0,
        100% calc(100% - 22px), calc(100% - 22px) 100%,
        22px 100%, 0 calc(100% - 22px));
    background-position: -19px -19px, left 0 top 0;
}
body:not(.standalone-mode) #view-tabs[data-edge-start][data-edge-end] + #views {
    /* a single tab is both first and last: fully square top */
    clip-path: polygon(
        0 0, 100% 0,
        100% calc(100% - 22px), calc(100% - 22px) 100%,
        22px 100%, 0 calc(100% - 22px));
    background-position: -19px -19px, -19px -19px;
}
#views::before,
#views::after {
    content: '';
    position: absolute;
    width: 34px;
    height: 1.5px;
    background: linear-gradient(90deg, transparent,
        color-mix(in srgb, #7ee8fa 80%, transparent) 45%,
        color-mix(in srgb, #b14aed 70%, transparent));
    pointer-events: none;
}
#views::before {
    bottom: 10px;
    right: -5px;
    transform: rotate(-45deg);
}
#views::after {
    bottom: 10px;
    left: -5px;
    transform: rotate(45deg);
}
.staging-group-head {
    clip-path: polygon(0 0, 100% 0, calc(100% - 10px) 100%, 0 100%);
}

/* 8. Tag chips keep the neon rim on hover; the empty states glow. */
.row-tag-chip {
    transition: box-shadow var(--vbm-dur-1) var(--vbm-ease),
        background-color var(--vbm-dur-1) var(--vbm-ease);
}
.row-tag-chip:hover {
    box-shadow: inset 0 0 0 1px color-mix(in srgb, #7ee8fa 55%, transparent),
        0 0 11px color-mix(in srgb, #7ee8fa 32%, transparent);
}
.empty-state {
    text-shadow: 0 0 18px color-mix(in srgb, #7ee8fa 32%, transparent);
}

/* 9. Scrollbars join the neon — thin, cyan, quiet until hovered. */
* {
    scrollbar-width: thin;
    scrollbar-color: color-mix(in srgb, #7ee8fa 30%, transparent) transparent;
}

/* 10. R8-5: the folder connector lines carry a travelling aurora current —
       a bright cyan-violet band glides down the dashed trunk (member rows
       and the group head's own drop alike). The dashes themselves still
       obey --staging-line, so the group-hover accent dye survives. */
@keyframes stg-glide {
    from { background-position: 0 -36px, 0 0, 0 0; }
    to { background-position: 0 140px, 0 0, 0 0; }
}
#staging-items li.vbm-row.staging-member > .staging-connector::before,
#staging-items li.staging-group.has-members::after,
#staging-items li.staging-bucket.has-members::after {
    background-image: linear-gradient(to bottom, transparent, color-mix(in srgb, #7ee8fa 95%, transparent) 45%, color-mix(in srgb, #b14aed 75%, transparent) 62%, transparent),
        repeating-linear-gradient(to bottom,
            var(--staging-line) 0 2px, transparent 2px 5px);
    background-size: 1px 36px, auto;
    background-repeat: no-repeat, repeat;
    animation: stg-glide 2.4s linear infinite;
}

/* 11. R9-4: the sky is ONE full-cover aurora + starfield (slice/cover — it
      never tiles at any aspect) and the ribbons DRIFT (SMIL inside the
      data-URL image, 26/34s parallax + an 18s shimmer). SMIL ignores the
      global reduced-motion clamp, so the static frame swaps in here. */
@media (prefers-reduced-motion: reduce) {
    body {
        --vbm-canvas-image: url(data:image/svg+xml;base64,), repeating-conic-gradient(color-mix(in srgb, #7ee8fa 2.5%, transparent) 0% 25%, transparent 0% 50%), repeating-conic-gradient(color-mix(in srgb, #b14aed 2%, transparent) 0% 25%, transparent 0% 50%);
    }
}

/* 12. R10 color pass: accent-as-TEXT lifts to the light violet rung —
      #9333d6 reads 3.15:1 on the sheet and only 2.25:1 on the selected
      tab's own fill (small-text AA needs 4.5); #c489f7 reads 7.06/5.06.
      Fills keep #9333d6 (white on it = 5.7:1) — the lift is text-only.
      Covers the selected view tab (label+icon ride currentColor) and every
      toolbar rung button (all compose .vbm-toolbar). */
.view-tab[aria-selected="true"] .tab-label { color: #c489f7; }
.vbm-toolbar button,
.vbm-toolbar button:hover:not([disabled]) { color: #c489f7; }

/* 13. R11: the sky breathes — a slow hue/brightness drift on the canvas
      layer. SMIL rides inside the image; this rides the page, so the
      combined parallax reads even over the glass. The global
      reduced-motion clamp still stops it cold. */
@keyframes aurora-breathe {
    0%, 100% { filter: hue-rotate(0deg) saturate(1) brightness(1); }
    50% { filter: hue-rotate(-22deg) saturate(1.22) brightness(1.1); }
}
/* R11.2: a KERNEL-INDEPENDENT pan — background-position pans the cover
      image along whichever axis has slack (horizontal on the tall popup,
      vertical on the wide canvas), so the sky drifts even where SMIL in
      image contexts is gone. Layer 1 only; the 4/7px grains stay put. */
@keyframes aurora-pan {
    0%, 100% { background-position: 34% 52%, 0 0, 0 0; }
    50% { background-position: 66% 40%, 0 0, 0 0; }
}
body::before {
    animation: aurora-breathe 22s ease-in-out infinite,
        aurora-pan 26s ease-in-out infinite;
}
